package com.b5.vpn;
import android.app.*;import android.os.*;import android.content.*;import com.b5.shared.*;import com.google.firebase.database.*;import de.blinkt.openvpn.core.*;
/** OpenVPN transport with a fail-closed TUN while a live service reconnects. */
public class B5VpnService extends OpenVPNService {
 public static volatile B5VpnService instance;public static volatile boolean connected=false,blockingTraffic=false;
 private final Handler handler=new Handler(Looper.getMainLooper());private Cloud cloud;private DatabaseReference codeRef;private ValueEventListener codeListener;private volatile long expiry=0;private volatile boolean entitlement=false,manual=false;private ParcelFileDescriptor blocker;private boolean initialCommand=true;
 @Override public void onCreate(){super.onCreate();instance=this;NotificationManager nm=getSystemService(NotificationManager.class);for(String id:new String[]{NOTIFICATION_CHANNEL_BG_ID,NOTIFICATION_CHANNEL_NEWSTATUS_ID,NOTIFICATION_CHANNEL_USERREQ_ID,"b5-guard"})nm.createNotificationChannel(new NotificationChannel(id,"B5 VPN • Connection",NotificationManager.IMPORTANCE_LOW));}
 boolean killEnabled(){return getSharedPreferences("b5",0).getBoolean("killSwitch",true);}
 @Override public int onStartCommand(Intent i,int flags,int id){String code=getSharedPreferences("b5",0).getString("code","");if(!Cloud.configured(this)||code.isEmpty()){stopSelf();return START_NOT_STICKY;}manual=false;cloud=new Cloud(this);if(codeRef!=null&&codeListener!=null)codeRef.removeEventListener(codeListener);codeRef=cloud.root.child("codes").child(code);codeListener=Cloud.listener(s->{entitlement=s.exists()&&Cloud.yes(s,"isActive")&&cloud.deviceId.equals(Cloud.str(s,"deviceId"))&&cloud.auth.getUid()!=null&&cloud.auth.getUid().equals(Cloud.str(s,"ownerUid"));expiry=Cloud.num(s,"expiryAt");if(!entitlement||Policy.expired(expiry,cloud.now()))shutdown();},e->shutdown());codeRef.addValueEventListener(codeListener);handler.removeCallbacks(tick);handler.post(tick);if(killEnabled()&&!connected)establishBlocker();initialCommand=false;return super.onStartCommand(i,flags,id);}
 void establishBlocker(){if(manual||blocker!=null)return;try{Builder b=new Builder().setSession("B5 Kill Switch • Traffic blocked").addAddress("10.254.254.1",32).addAddress("fd55:b5::1",128).addRoute("0.0.0.0",0).addRoute("::",0).addDnsServer("10.254.254.2").setBlocking(true).setUnderlyingNetworks(null);blocker=b.establish();blockingTraffic=blocker!=null;if(blockingTraffic)startForeground(5507,guardNotification());}catch(Exception e){blockingTraffic=false;VpnStatus.logError("B5 traffic guard failed: "+e.getMessage());}}
 Notification guardNotification(){return new Notification.Builder(this,"b5-guard").setSmallIcon(com.usa.user.R.drawable.ic_b5).setContentTitle("B5 Kill Switch • Traffic blocked").setContentText("Open USA-Favor to reconnect or disable Kill Switch").setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,com.usa.user.MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).setOngoing(true).build();}
 void releaseBlocker(){if(blocker!=null){try{blocker.close();}catch(Exception ignored){}blocker=null;}blockingTraffic=false;getSystemService(NotificationManager.class).cancel(5507);}
 public void applyKillSwitch(){if(!killEnabled())releaseBlocker();else if(!connected)establishBlocker();}
 @Override public ParcelFileDescriptor openTun(){ParcelFileDescriptor p=super.openTun();if(p!=null)releaseBlocker();return p;}
 @Override protected boolean keepServiceAfterDisconnect(){boolean keep=!manual&&killEnabled()&&entitlement;if(keep)establishBlocker();return keep;}
 final Runnable tick=new Runnable(){public void run(){if(cloud!=null&&expiry>0&&Policy.expired(expiry,cloud.now())){shutdown();return;}handler.postDelayed(this,1000);}};
 @Override public boolean stopVPN(boolean replacement)throws RemoteException{if(!replacement){manual=true;stopService(new Intent(this,MockLocationService.class));releaseBlocker();}return super.stopVPN(replacement);}
 public void shutdown(){manual=true;connected=false;stopService(new Intent(this,MockLocationService.class));releaseBlocker();try{stopVPN(false);}catch(Exception ignored){}stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 public static void disconnect(){B5VpnService x=instance;if(x!=null)x.shutdown();}
 @Override public void updateState(String state,String log,int res,ConnectionStatus level,Intent intent){super.updateState(state,log,res,level,intent);boolean old=connected;connected=level==ConnectionStatus.LEVEL_CONNECTED;if(connected){releaseBlocker();MockLocationService.startIfPermitted(this);Notification n=new Notification.Builder(this,NOTIFICATION_CHANNEL_NEWSTATUS_ID).setSmallIcon(com.usa.user.R.drawable.ic_b5).setContentTitle("Connected to USA - B5 VPN").setContentText("Open USA-Favor to verify exit IP and country").setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,com.usa.user.MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).setOngoing(true).build();getSystemService(NotificationManager.class).notify(5505,n);}else{stopService(new Intent(this,MockLocationService.class));getSystemService(NotificationManager.class).cancel(5505);if(!manual&&killEnabled()&&(level==ConnectionStatus.LEVEL_NOTCONNECTED||level==ConnectionStatus.LEVEL_AUTH_FAILED))handler.post(this::establishBlocker);}}
 @Override public void onRevoke(){manual=true;releaseBlocker();stopService(new Intent(this,MockLocationService.class));try{super.onRevoke();}catch(Exception ignored){}stopSelf();}
 @Override public void onDestroy(){manual=true;handler.removeCallbacksAndMessages(null);if(codeRef!=null&&codeListener!=null)codeRef.removeEventListener(codeListener);stopService(new Intent(this,MockLocationService.class));releaseBlocker();connected=false;instance=null;getSystemService(NotificationManager.class).cancel(5505);super.onDestroy();}
}
